<!doctype html>
<html lang="en">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width, initial-scale=1">
<title>Void Drifter</title>
<style>
  html, body { margin: 0; height: 100%; overflow: hidden; background: #0a0a12; }
  #game { position: fixed; inset: 0; width: 100%; height: 100%; display: block; touch-action: none; }
  #status { position: absolute; width: 1px; height: 1px; overflow: hidden; clip-path: inset(50%); white-space: nowrap; }
</style>
</head>
<body>
<canvas id="game" aria-label="Void Drifter: survive the asteroid field"></canvas>
<p id="status" role="status" aria-live="polite"></p>
<script>
'use strict';
const canvas = document.getElementById('game');
const ctx = canvas.getContext('2d');

// ---- URL params: ?shot=start|play|end and ?seed=N for deterministic screenshots ----
const params = new URLSearchParams(location.search);
const SHOT = params.get('shot');           // null in normal play
const SEED = params.get('seed');
const SHOT_MODE = SHOT === 'start' || SHOT === 'play' || SHOT === 'end';

// Seeded RNG (mulberry32) so screenshot mode is deterministic; Math.random in live play.
let seedState = SEED === null ? 0 : (parseInt(SEED, 10) >>> 0 || 1);
function rng() {
  if (SEED === null) return Math.random();
  seedState = (seedState + 0x6D2B79F5) >>> 0;
  let t = seedState;
  t = Math.imul(t ^ (t >>> 15), t | 1);
  t ^= t + Math.imul(t ^ (t >>> 7), t | 61);
  return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
}
const FROZEN_NOW = 1000; // fixed clock for screenshot frames

let W, H;
function resize() { W = canvas.width = innerWidth; H = canvas.height = innerHeight; }
resize();
addEventListener('resize', resize);

// ---- Sound: synthesized Web Audio, no files, no network ----
let audioCtx = null, muted = false;
function ensureAudio() {
  if (!audioCtx) {
    try { audioCtx = new (window.AudioContext || window.webkitAudioContext)(); } catch (e) { audioCtx = null; }
  }
  if (audioCtx && audioCtx.state === 'suspended') audioCtx.resume();
}
function tone(freq, dur, type, vol, slideTo) {
  if (!audioCtx || muted) return;
  const t = audioCtx.currentTime;
  const o = audioCtx.createOscillator();
  const g = audioCtx.createGain();
  o.type = type || 'sine';
  o.frequency.setValueAtTime(freq, t);
  if (slideTo) o.frequency.exponentialRampToValueAtTime(slideTo, t + dur);
  g.gain.setValueAtTime(vol || 0.12, t);
  g.gain.exponentialRampToValueAtTime(0.001, t + dur);
  o.connect(g); g.connect(audioCtx.destination);
  o.start(t); o.stop(t + dur);
}
function noiseBurst(dur, vol) {
  if (!audioCtx || muted) return;
  const t = audioCtx.currentTime;
  const len = Math.floor(audioCtx.sampleRate * dur);
  const buf = audioCtx.createBuffer(1, len, audioCtx.sampleRate);
  const d = buf.getChannelData(0);
  for (let i = 0; i < len; i++) d[i] = (Math.random() * 2 - 1) * (1 - i / len);
  const src = audioCtx.createBufferSource();
  src.buffer = buf;
  const f = audioCtx.createBiquadFilter();
  f.type = 'lowpass'; f.frequency.value = 700;
  const g = audioCtx.createGain();
  g.gain.setValueAtTime(vol || 0.3, t);
  g.gain.exponentialRampToValueAtTime(0.001, t + dur);
  src.connect(f); f.connect(g); g.connect(audioCtx.destination);
  src.start(t);
}
function sfx(name) {
  if (name === 'start') { tone(440, 0.15, 'square', 0.07, 880); }
  else if (name === 'near') { tone(1320, 0.08, 'sine', 0.07); }
  else if (name === 'shard') { tone(880, 0.1, 'sine', 0.12, 1320); tone(1760, 0.14, 'sine', 0.06); }
  else if (name === 'death') { noiseBurst(0.5, 0.3); tone(160, 0.5, 'sawtooth', 0.14, 40); }
  else if (name === 'milestone') { tone(660, 0.1, 'sine', 0.1); setTimeout(function () { tone(990, 0.14, 'sine', 0.1); }, 110); }
  else if (name === 'click') { tone(520, 0.06, 'square', 0.05); }
}

// ---- State ----
let state = 'start'; // 'start' | 'play' | 'paused' | 'gameover'
let score = 0;
let playTime = 0;        // accumulated seconds of play (pauses excluded)
let nearMissBonus = 0;
let shardBonus = 0;
let lastMilestone = 0;
let toastText = '', toastUntil = 0;
let best = 0;
try { best = parseInt(localStorage.getItem('void-drifter-best') || '0', 10) || 0; } catch (e) { best = 0; }
if (SHOT_MODE) best = 0;

const ship = { x: 0, y: 0, tx: 0, ty: 0, r: 14 };

let asteroids = [];
let asteroidTimer = 0;
let spawnRate = 1.5;
let difficulty = 1;

let shards = [];
let shardTimer = 0;

let particles = [];

let stars = [];
function initStars() {
  stars = [];
  for (let i = 0; i < 200; i++) {
    stars.push({ x: rng() * W, y: rng() * H, bright: 0.3 + rng() * 0.7, size: 0.5 + rng() * 1.5 });
  }
}
initStars();

function genVerts() {
  const n = 7 + Math.floor(rng() * 4);
  const verts = [];
  for (let i = 0; i < n; i++) {
    const a = (i / n) * Math.PI * 2;
    const r = 0.65 + rng() * 0.7;
    verts.push({ x: Math.cos(a) * r, y: Math.sin(a) * r });
  }
  return verts;
}

function randomEdge() {
  const edge = Math.floor(rng() * 4);
  let x, y, vx, vy;
  const speed = (1.5 + rng() * 2) * difficulty;
  if (edge === 0) { x = rng() * W; y = -60; vx = (rng() - 0.5) * 1.5; vy = speed; }
  else if (edge === 1) { x = W + 60; y = rng() * H; vx = -speed; vy = (rng() - 0.5) * 1.5; }
  else if (edge === 2) { x = rng() * W; y = H + 60; vx = (rng() - 0.5) * 1.5; vy = -speed; }
  else { x = -60; y = rng() * H; vx = speed; vy = (rng() - 0.5) * 1.5; }
  return { x, y, vx, vy, r: 18 + rng() * 22, rot: rng() * Math.PI * 2, rotV: (rng() - 0.5) * 0.04, verts: genVerts(), nearMissed: false };
}

function spawnParticles(x, y, count, color, speedMult) {
  for (let i = 0; i < count; i++) {
    const a = rng() * Math.PI * 2;
    const spd = (2 + rng() * 4) * (speedMult || 1);
    particles.push({ x, y, vx: Math.cos(a) * spd, vy: Math.sin(a) * spd, life: 1, color, size: 2 + rng() * 4 });
  }
}

function spawnShard() {
  if (shards.length >= 3) return;
  shards.push({
    x: 60 + rng() * (W - 120), y: 60 + rng() * (H - 120),
    vx: (rng() - 0.5) * 0.4, vy: (rng() - 0.5) * 0.4,
    rot: rng() * Math.PI, rotV: 0.02, r: 12
  });
}

function showToast(text, ms) {
  toastText = text;
  toastUntil = (SHOT_MODE ? FROZEN_NOW : performance.now()) + ms;
}

function startGame() {
  state = 'play';
  playTime = 0;
  score = 0;
  nearMissBonus = 0;
  shardBonus = 0;
  lastMilestone = 0;
  asteroids = [];
  shards = [];
  particles = [];
  difficulty = 1;
  spawnRate = 1.5;
  asteroidTimer = 0;
  shardTimer = 2;
  ship.x = W / 2; ship.y = H / 2;
  ship.tx = mx; ship.ty = my;
  sfx('start');
}

function endGame() {
  score = Math.floor(playTime * 10) + nearMissBonus + shardBonus;
  if (!SHOT_MODE && score > best) {
    best = score;
    try { localStorage.setItem('void-drifter-best', String(best)); } catch (e) {}
  }
  spawnParticles(ship.x, ship.y, 40, '#ff4444', 2);
  addShake(20);
  sfx('death');
  state = 'gameover';
}

// ---- Input: mouse + keyboard ----
let mx = W / 2, my = H / 2;
const keys = {};
canvas.addEventListener('mousemove', function (e) { mx = e.clientX; my = e.clientY; });
canvas.addEventListener('click', function () {
  ensureAudio();
  if (state === 'start') { startGame(); }
  else if (state === 'gameover') { state = 'start'; sfx('click'); }
  else if (state === 'paused') { state = 'play'; }
});
addEventListener('keydown', function (e) {
  ensureAudio();
  const k = e.key.toLowerCase();
  keys[k] = true;
  if (k === ' ' || k === 'enter') {
    e.preventDefault();
    if (state === 'start') startGame();
    else if (state === 'gameover') { state = 'start'; sfx('click'); }
    else if (state === 'paused') state = 'play';
  } else if (k === 'p') {
    if (state === 'play') state = 'paused';
    else if (state === 'paused') state = 'play';
  } else if (k === 'm') {
    muted = !muted;
  }
  if (['arrowup', 'arrowdown', 'arrowleft', 'arrowright', ' '].indexOf(k) !== -1) e.preventDefault();
});
addEventListener('keyup', function (e) { keys[e.key.toLowerCase()] = false; });

// ---- Screen shake ----
let shake = 0;
function addShake(v) { shake = Math.max(shake, v); }

// ---- Update ----
function update(dt) {
  if (state !== 'play') return;

  playTime += dt;
  difficulty = 1 + playTime / 30;
  spawnRate = Math.max(0.4, 1.5 - playTime / 60);

  // Milestone chime every 30 seconds survived
  if (Math.floor(playTime / 30) > Math.floor(lastMilestone / 30)) {
    lastMilestone = playTime;
    sfx('milestone');
    showToast(Math.floor(playTime) + 's SURVIVED!', 2000);
  }

  // Keyboard thrust (arrows / WASD); mouse sets the target the ship lerps toward.
  const KB_SPEED = 420;
  let kx = (keys['arrowright'] || keys['d'] ? 1 : 0) - (keys['arrowleft'] || keys['a'] ? 1 : 0);
  let ky = (keys['arrowdown'] || keys['s'] ? 1 : 0) - (keys['arrowup'] || keys['w'] ? 1 : 0);
  if (kx !== 0 || ky !== 0) {
    const len = Math.sqrt(kx * kx + ky * ky);
    ship.x += (kx / len) * KB_SPEED * dt;
    ship.y += (ky / len) * KB_SPEED * dt;
    ship.tx = ship.x; ship.ty = ship.y; // keep mouse target in sync so it does not fight the keys
  } else {
    ship.tx = mx; ship.ty = my;
    ship.x += (ship.tx - ship.x) * 0.1;
    ship.y += (ship.ty - ship.y) * 0.1;
  }
  ship.x = Math.max(ship.r, Math.min(W - ship.r, ship.x));
  ship.y = Math.max(ship.r, Math.min(H - ship.r, ship.y));

  // Spawn asteroids
  asteroidTimer += dt;
  if (asteroidTimer >= spawnRate) {
    asteroidTimer = 0;
    asteroids.push(randomEdge());
  }

  // Spawn star shards (collectibles)
  shardTimer += dt;
  if (shardTimer >= 4) {
    shardTimer = 0;
    spawnShard();
  }

  // Update asteroids
  for (let i = asteroids.length - 1; i >= 0; i--) {
    const a = asteroids[i];
    a.x += a.vx;
    a.y += a.vy;
    a.rot += a.rotV;

    if (a.x < -120 || a.x > W + 120 || a.y < -120 || a.y > H + 120) {
      asteroids.splice(i, 1);
      continue;
    }

    const dx = a.x - ship.x, dy = a.y - ship.y;
    const dist = Math.sqrt(dx * dx + dy * dy);
    if (dist < a.r + ship.r - 4) {
      endGame();
      return;
    }

    // Near miss: within 30px, bonus once per asteroid (persistent flag, not per-frame).
    if (!a.nearMissed && dist < a.r + ship.r + 30) {
      a.nearMissed = true;
      nearMissBonus += 5;
      spawnParticles(ship.x, ship.y, 8, '#ffd700', 0.8);
      sfx('near');
    }
  }

  // Update shards
  for (let i = shards.length - 1; i >= 0; i--) {
    const s = shards[i];
    s.x += s.vx; s.y += s.vy; s.rot += s.rotV;
    if (s.x < 20 || s.x > W - 20) s.vx *= -1;
    if (s.y < 20 || s.y > H - 20) s.vy *= -1;
    const dx = s.x - ship.x, dy = s.y - ship.y;
    if (Math.sqrt(dx * dx + dy * dy) < ship.r + s.r + 4) {
      shards.splice(i, 1);
      shardBonus += 25;
      spawnParticles(s.x, s.y, 14, '#00ffff', 1);
      sfx('shard');
    }
  }

  // Update particles
  for (let i = particles.length - 1; i >= 0; i--) {
    const p = particles[i];
    p.x += p.vx; p.y += p.vy;
    p.vx *= 0.96; p.vy *= 0.96;
    p.life -= dt * 2;
    if (p.life <= 0) particles.splice(i, 1);
  }

  shake *= 0.88;
}

// ---- Render ----
function drawShip() {
  const x = ship.x, y = ship.y;
  ctx.save();
  ctx.translate(x, y);
  const grd = ctx.createRadialGradient(0, 0, 0, 0, 0, ship.r * 2.5);
  grd.addColorStop(0, 'rgba(0,255,255,0.25)');
  grd.addColorStop(1, 'rgba(0,255,255,0)');
  ctx.fillStyle = grd;
  ctx.beginPath();
  ctx.arc(0, 0, ship.r * 2.5, 0, Math.PI * 2);
  ctx.fill();
  ctx.fillStyle = '#00ffff';
  ctx.shadowColor = '#00ffff';
  ctx.shadowBlur = 18;
  ctx.beginPath();
  ctx.moveTo(0, -ship.r);
  ctx.lineTo(-ship.r * 0.75, ship.r * 0.8);
  ctx.lineTo(0, ship.r * 0.4);
  ctx.lineTo(ship.r * 0.75, ship.r * 0.8);
  ctx.closePath();
  ctx.fill();
  ctx.fillStyle = '#003333';
  ctx.shadowBlur = 0;
  ctx.beginPath();
  ctx.ellipse(0, 0, ship.r * 0.3, ship.r * 0.5, 0, 0, Math.PI * 2);
  ctx.fill();
  ctx.restore();
}

function drawAsteroid(a) {
  ctx.save();
  ctx.translate(a.x, a.y);
  ctx.rotate(a.rot);
  ctx.fillStyle = '#7a5040';
  ctx.strokeStyle = '#5a3828';
  ctx.lineWidth = 2;
  ctx.shadowColor = 'rgba(0,0,0,0.5)';
  ctx.shadowBlur = 4;
  ctx.beginPath();
  ctx.moveTo(a.verts[0].x * a.r, a.verts[0].y * a.r);
  for (let i = 1; i < a.verts.length; i++) {
    ctx.lineTo(a.verts[i].x * a.r, a.verts[i].y * a.r);
  }
  ctx.closePath();
  ctx.fill();
  ctx.stroke();
  ctx.restore();
}

function drawShard(s) {
  ctx.save();
  ctx.translate(s.x, s.y);
  ctx.rotate(s.rot);
  ctx.fillStyle = '#00ffff';
  ctx.shadowColor = '#00ffff';
  ctx.shadowBlur = 14;
  ctx.beginPath();
  ctx.moveTo(0, -s.r);
  ctx.lineTo(s.r * 0.7, 0);
  ctx.lineTo(0, s.r);
  ctx.lineTo(-s.r * 0.7, 0);
  ctx.closePath();
  ctx.fill();
  ctx.restore();
}

function drawParticles() {
  for (const p of particles) {
    ctx.globalAlpha = p.life;
    ctx.fillStyle = p.color;
    ctx.beginPath();
    ctx.arc(p.x, p.y, p.size * p.life, 0, Math.PI * 2);
    ctx.fill();
  }
  ctx.globalAlpha = 1;
}

function drawStars() {
  for (const s of stars) {
    ctx.globalAlpha = s.bright * 0.8;
    ctx.fillStyle = '#ffffff';
    ctx.beginPath();
    ctx.arc(s.x, s.y, s.size, 0, Math.PI * 2);
    ctx.fill();
  }
  ctx.globalAlpha = 1;
}

function currentScore() {
  return Math.floor(playTime * 10) + nearMissBonus + shardBonus;
}

function drawHUD(now) {
  ctx.font = 'bold 18px monospace';
  ctx.fillStyle = '#00ffff';
  ctx.shadowColor = '#00ffff';
  ctx.shadowBlur = 10;
  ctx.textAlign = 'left';
  ctx.fillText('SCORE ' + currentScore(), 20, 36);
  ctx.textAlign = 'right';
  ctx.fillText('TIME ' + Math.floor(playTime) + 's', W - 20, 36);
  ctx.textAlign = 'center';
  ctx.fillText('BEST ' + best, W / 2, 36);
  ctx.shadowBlur = 0;
  if (toastText && now < toastUntil) {
    ctx.font = 'bold 20px monospace';
    ctx.fillStyle = '#ffd700';
    ctx.shadowColor = '#ffd700';
    ctx.shadowBlur = 12;
    ctx.fillText(toastText, W / 2, 70);
    ctx.shadowBlur = 0;
  }
  if (muted) {
    ctx.font = '14px monospace';
    ctx.fillStyle = '#888888';
    ctx.textAlign = 'right';
    ctx.fillText('[MUTED]', W - 20, H - 16);
  }
}

function drawStartScreen(now) {
  ctx.font = 'bold 52px monospace';
  ctx.fillStyle = '#00ffff';
  ctx.shadowColor = '#00ffff';
  ctx.shadowBlur = 30;
  ctx.textAlign = 'center';
  ctx.fillText('VOID DRIFTER', W / 2, H / 2 - 90);
  ctx.font = '18px monospace';
  ctx.shadowBlur = 10;
  ctx.fillText('SURVIVE THE ASTEROID FIELD', W / 2, H / 2 - 45);
  ctx.font = '14px monospace';
  ctx.fillStyle = '#aaaacc';
  ctx.shadowBlur = 0;
  ctx.fillText('Dodge asteroids - grab star shards (+25) - near misses earn +5', W / 2, H / 2 - 10);
  ctx.fillText('Mouse steers - Arrow keys / WASD fly - P pauses - M mutes', W / 2, H / 2 + 16);
  if (best > 0) {
    ctx.fillStyle = '#ffd700';
    ctx.fillText('BEST SCORE: ' + best, W / 2, H / 2 + 44);
  }
  const pulse = 0.6 + 0.4 * Math.sin(now / 400);
  ctx.globalAlpha = pulse;
  ctx.font = 'bold 22px monospace';
  ctx.fillStyle = '#ffd700';
  ctx.shadowColor = '#ffd700';
  ctx.shadowBlur = 15;
  ctx.fillText('[ CLICK OR PRESS SPACE TO BEGIN ]', W / 2, H / 2 + 92);
  ctx.globalAlpha = 1;
  ctx.shadowBlur = 0;
}

function drawGameOver(now) {
  ctx.fillStyle = 'rgba(0,0,0,0.7)';
  ctx.fillRect(0, 0, W, H);
  ctx.font = 'bold 44px monospace';
  ctx.fillStyle = '#ff4444';
  ctx.shadowColor = '#ff4444';
  ctx.shadowBlur = 25;
  ctx.textAlign = 'center';
  ctx.fillText('GAME OVER', W / 2, H / 2 - 60);
  ctx.font = 'bold 28px monospace';
  ctx.fillStyle = '#00ffff';
  ctx.shadowColor = '#00ffff';
  ctx.shadowBlur = 15;
  ctx.fillText('FINAL SCORE: ' + score, W / 2, H / 2);
  ctx.font = '16px monospace';
  ctx.fillStyle = '#aaaacc';
  ctx.shadowBlur = 0;
  ctx.fillText('Survived ' + playTime.toFixed(1) + 's  -  Best ' + best, W / 2, H / 2 + 34);
  const pulse = 0.6 + 0.4 * Math.sin(now / 400);
  ctx.globalAlpha = pulse;
  ctx.font = 'bold 18px monospace';
  ctx.fillStyle = '#ffd700';
  ctx.shadowColor = '#ffd700';
  ctx.shadowBlur = 12;
  ctx.fillText('[ CLICK OR PRESS SPACE TO RESTART ]', W / 2, H / 2 + 78);
  ctx.globalAlpha = 1;
  ctx.shadowBlur = 0;
}

function drawPaused() {
  ctx.fillStyle = 'rgba(0,0,0,0.6)';
  ctx.fillRect(0, 0, W, H);
  ctx.font = 'bold 40px monospace';
  ctx.fillStyle = '#00ffff';
  ctx.shadowColor = '#00ffff';
  ctx.shadowBlur = 20;
  ctx.textAlign = 'center';
  ctx.fillText('PAUSED', W / 2, H / 2);
  ctx.font = '16px monospace';
  ctx.fillStyle = '#aaaacc';
  ctx.shadowBlur = 0;
  ctx.fillText('Press P or click to resume', W / 2, H / 2 + 36);
}

function drawScene(now) {
  ctx.save();
  if (shake > 0.5) {
    ctx.translate((rng() - 0.5) * shake, (rng() - 0.5) * shake);
  }
  ctx.fillStyle = '#0a0a12';
  ctx.fillRect(-30, -30, W + 60, H + 60);
  drawStars();
  if (state === 'start') {
    drawStartScreen(now);
  } else if (state === 'play') {
    for (const a of asteroids) drawAsteroid(a);
    for (const s of shards) drawShard(s);
    drawParticles();
    drawShip();
    drawHUD(now);
  } else if (state === 'paused') {
    for (const a of asteroids) drawAsteroid(a);
    for (const s of shards) drawShard(s);
    drawParticles();
    drawShip();
    drawHUD(now);
    drawPaused();
  } else if (state === 'gameover') {
    for (const a of asteroids) drawAsteroid(a);
    drawParticles();
    drawShip();
    drawGameOver(now);
  }
  ctx.restore();
}

// ---- Screenshot mode: one deterministic frozen frame per shot ----
function buildShotScene() {
  if (SHOT === 'start') {
    state = 'start';
    ship.x = W / 2; ship.y = H / 2;
  } else if (SHOT === 'play') {
    state = 'play';
    playTime = 12.5;
    nearMissBonus = 15;
    shardBonus = 25;
    ship.x = W / 2; ship.y = H / 2 - 40;
    ship.tx = ship.x; ship.ty = ship.y;
    asteroids = [];
    for (let i = 0; i < 8; i++) {
      const a = randomEdge();
      a.x = 80 + rng() * (W - 160);
      a.y = 60 + rng() * (H - 160);
      asteroids.push(a);
    }
    shards = [{ x: W / 2 + 120, y: H / 2 + 60, vx: 0, vy: 0, rot: 0.6, rotV: 0, r: 12 }];
    spawnParticles(ship.x - 90, ship.y + 50, 6, '#ffd700', 0.8);
  } else if (SHOT === 'end') {
    state = 'gameover';
    playTime = 24.7;
    score = 247;
    ship.x = W / 2; ship.y = H / 2;
    asteroids = [];
    for (let i = 0; i < 5; i++) {
      const a = randomEdge();
      a.x = 100 + rng() * (W - 200);
      a.y = 80 + rng() * (H - 160);
      asteroids.push(a);
    }
    spawnParticles(ship.x, ship.y, 30, '#ff4444', 1.5);
  }
  drawScene(FROZEN_NOW);
}

// ---- Main loop ----
let lastT = performance.now();
function loop(now) {
  const dt = Math.min((now - lastT) / 1000, 0.05);
  lastT = now;
  update(dt);
  drawScene(now);
  requestAnimationFrame(loop);
}

if (SHOT_MODE) {
  buildShotScene();
} else {
  ship.x = W / 2; ship.y = H / 2;
  ship.tx = mx; ship.ty = my;
  requestAnimationFrame(loop);
}
</script>
</body>
</html>
```
